This will handle permissions, `AudioRecord`, `AudioTrack`, threading, and calling the JNI functions.

```kotlin
package com.yourcompany.yourappname // Replace with your package name

import android.Manifest
import android.content.pm.PackageManager
import android.media.*
import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import android.util.Log
import android.widget.Button
import androidx.core.app.ActivityCompat
import androidx.core.content.ContextCompat
import kotlinx.coroutines.*
import java.nio.ByteBuffer
import java.nio.ByteOrder
import kotlin.coroutines.CoroutineContext

class MainActivity : AppCompatActivity(), CoroutineScope {

    private val TAG = "ReverbMic"
    private val RECORD_AUDIO_PERMISSION_REQUEST_CODE = 101

    private lateinit var startButton: Button
    private lateinit var stopButton: Button

    private var audioRecord: AudioRecord? = null
    private var audioTrack: AudioTrack? = null
    private var isRecording = false

    private val sampleRate = 44100 // Standard sample rate
    private val channelConfig = AudioFormat.CHANNEL_IN_MONO
    private val audioFormat = AudioFormat.ENCODING_PCM_16BIT
    private val playbackChannelConfig = AudioFormat.CHANNEL_OUT_MONO

    // Simple reverb parameters (adjust as needed)
    private val reverbDelayMs = 100 // Delay in milliseconds
    private val reverbGain = 0.5f   // Gain of the delayed signal

    private var audioJob: Job? = null
    private val coroutineExceptionHandler = CoroutineExceptionHandler { _, throwable ->
        Log.e(TAG, "Coroutine failed: ${throwable.message}", throwable)
        // Handle the error, maybe stop recording/playback
        runOnUiThread { stopRecording() }
    }

    override val coroutineContext: CoroutineContext
        get() = Dispatchers.IO + coroutineExceptionHandler

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        startButton = findViewById(R.id.startButton)
        stopButton = findViewById(R.id.stopButton)

        startButton.setOnClickListener {
            if (checkPermissions()) {
                startRecording()
            } else {
                requestPermissions()
            }
        }

        stopButton.setOnClickListener {
            stopRecording()
        }

        updateButtonState()
    }

    private fun checkPermissions(): Boolean {
        return ContextCompat.checkSelfPermission(
            this,
            Manifest.permission.RECORD_AUDIO
        ) == PackageManager.PERMISSION_GRANTED
    }

    private fun requestPermissions() {
        ActivityCompat.requestPermissions(
            this,
            arrayOf(Manifest.permission.RECORD_AUDIO),
            RECORD_AUDIO_PERMISSION_REQUEST_CODE
        )
    }

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<out String>,
        grantResults: IntArray
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == RECORD_AUDIO_PERMISSION_REQUEST_CODE) {
            if (grantResults.isNotEmpty() && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                Log.d(TAG, "RECORD_AUDIO permission granted")
                // Permission granted, user can now start recording
                updateButtonState() // Enable start button if needed
            } else {
                Log.w(TAG, "RECORD_AUDIO permission denied")
                // Permission denied, show a message or disable functionality
                // updateButtonState(); // Keep start button disabled
            }
        }
    }

    private fun startRecording() {
        if (isRecording) {
            Log.d(TAG, "Already recording")
            return
        }

        Log.d(TAG, "Starting recording...")
        isRecording = true
        updateButtonState()

        audioJob = launch {
            try {
                // Initialize AudioRecord
                val minBufferSize = AudioRecord.getMinBufferSize(
                    sampleRate,
                    channelConfig,
                    audioFormat
                )
                if (minBufferSize == AudioRecord.ERROR || minBufferSize == AudioRecord.ERROR_BAD_VALUE) {
                    throw IllegalStateException("Failed to get minimum buffer size")
                }
                 // Choose a buffer size that is a multiple of minBufferSize, e.g., 2x or 4x
                val bufferSize = minBufferSize * 2
                Log.d(TAG, "Min buffer size: $minBufferSize, Using buffer size: $bufferSize")

                audioRecord = AudioRecord(
                    MediaRecorder.AudioSource.MIC,
                    sampleRate,
                    channelConfig,
                    audioFormat,
                    bufferSize
                )

                if (audioRecord?.state != AudioRecord.STATE_INITIALIZED) {
                    throw IllegalStateException("AudioRecord initialization failed")
                }

                // Initialize AudioTrack for playback
                 audioTrack = AudioTrack.Builder()
                     .setAudioAttributes(
                         AudioAttributes.Builder()
                             .setUsage(AudioAttributes.USAGE_MEDIA)
                             .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)
                             .build()
                     )
                     .setAudioFormat(
                         AudioFormat.Builder()
                             .setEncoding(audioFormat)
                             .setSampleRate(sampleRate)
                             .setChannelMask(playbackChannelConfig)
                             .build()
                     )
                     .setBufferSizeInBytes(bufferSize)
                     .setPerformanceMode(AudioTrack.PERFORMANCE_MODE_LOW_LATENCY) // Try low latency if available
                     .build()

                if (audioTrack?.state != AudioTrack.STATE_INITIALIZED) {
                    Log.w(TAG, "AudioTrack initialization failed, continuing without playback")
                    audioTrack = null // Don't use if initialization failed
                } else {
                     audioTrack?.play()
                     Log.d(TAG, "AudioTrack initialized and playing")
                }


                // Initialize native reverb processor
                val initResult = ReverbNative.initReverb(sampleRate, reverbDelayMs, reverbGain)
                if (initResult != 0) {
                    throw IllegalStateException("Native reverb initialization failed: $initResult")
                }
                Log.d(TAG, "Native reverb initialized")

                // Start recording
                audioRecord?.startRecording()
                if (audioRecord?.recordingState != AudioRecord.RECORDSTATE_RECORDING) {
                     throw IllegalStateException("AudioRecord failed to start recording")
                }
                Log.d(TAG, "AudioRecord started")

                // Audio processing loop
                val audioBuffer = ShortArray(bufferSize / 2) // bufferSize is in bytes, Short is 2 bytes
                while (isRecording && !currentCoroutineContext().isActive) { // Check isRecording and coroutine state
                    val samplesRead = audioRecord?.read(audioBuffer, 0, audioBuffer.size) ?: 0

                    if (samplesRead > 0) {
                        // Process the audio buffer using native code
                        ReverbNative.processBuffer(audioBuffer, samplesRead)

                        // Play the processed audio
                        audioTrack?.write(audioBuffer, 0, samplesRead)
                    } else if (samplesRead < 0) {
                        Log.e(TAG, "AudioRecord read error: $samplesRead")
                        break // Exit loop on error
                    }
                    // Small delay to avoid 100% CPU usage in some cases, adjust if needed
                    // yield() // Or delay(1)
                }

            } catch (e: Exception) {
                Log.e(TAG, "Error during audio processing", e)
                runOnUiThread {
                    // Optionally show an error message to the user
                }
            } finally {
                Log.d(TAG, "Stopping audio processing loop")
                // Clean up resources
                audioRecord?.stop()
                audioRecord?.release()
                audioRecord = null
                Log.d(TAG, "AudioRecord released")

                audioTrack?.stop()
                audioTrack?.release()
                audioTrack = null
                Log.d(TAG, "AudioTrack released")

                ReverbNative.releaseReverb()
                Log.d(TAG, "Native reverb released")

                isRecording = false
                runOnUiThread { updateButtonState() }
                Log.d(TAG, "Recording stopped")
            }
        }
    }

    private fun stopRecording() {
        if (!isRecording) {
            Log.d(TAG, "Not currently recording")
            return
        }
        Log.d(TAG, "Requesting stop recording...")
        // Set the flag to false to signal the processing loop to stop
        isRecording = false
        // Cancel the coroutine job if it's active
        audioJob?.cancel()
        // The finally block in the coroutine will handle resource cleanup
        updateButtonState()
    }

    private fun updateButtonState() {
        runOnUiThread {
            startButton.isEnabled = !isRecording && checkPermissions()
            stopButton.isEnabled = isRecording
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        // Ensure recording is stopped when activity is destroyed
        stopRecording()
    }
}
