```cpp
#include <jni.h>
#include <vector>
#include <cmath>
#include <android/log.h>
#include <limits> // For SHRT_MAX

#define TAG "ReverbNative_CPP"
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, TAG, __VA_ARGS__)
#define LOGE(...) __android_log_print(ANDROID_LOG_ERROR, TAG, __VA_ARGS__)
#define LOGD(...) __android_log_print(ANDROID_LOG_DEBUG, TAG, __VA_ARGS__)

// --- Native Reverb State ---
namespace { // Anonymous namespace for internal linkage

std::vector<float> delayLine;
int delaySamples = 0;
float reverbGain = 0.0f;
int writeIndex = 0;
bool isInitialized = false;

// Helper function to clip float sample back to short range
inline short floatToShort(float sample) {
    if (sample > 1.0f) return std::numeric_limits<short>::max();
    if (sample < -1.0f) return std::numeric_limits<short>::min();
    return static_cast<short>(sample * std::numeric_limits<short>::max());
}

// Helper function to convert short sample to float
inline float shortToFloat(short sample) {
    return static_cast<float>(sample) / std::numeric_limits<short>::max();
}

} // namespace

// --- JNI Function Implementations ---

extern "C" JNIEXPORT jint JNICALL
Java_com_yourcompany_yourappname_ReverbNative_initReverb( // Replace with your package name
    JNIEnv *env,
    jobject /* this */,
    jint sampleRate,
    jint delayMs,
    jfloat gain) {

    if (isInitialized) {
        LOGW("Reverb already initialized. Releasing first.");
        // Optionally release existing resources before re-initializing
        // releaseReverb(); // This would need to be called from C++
        // For simplicity in this example, we'll just return an error or handle it
        return -1; // Indicate already initialized
    }

    if (sampleRate <= 0 || delayMs < 0 || gain < 0.0f || gain > 1.0f) {
        LOGE("Invalid parameters: sampleRate=%d, delayMs=%d, gain=%f", sampleRate, delayMs, gain);
        return -2; // Indicate invalid parameters
    }

    // Calculate delay in samples
    delaySamples = static_cast<int>((static_cast<float>(delayMs) / 1000.0f) * sampleRate);

    if (delaySamples <= 0) {
         LOGW("Calculated delay samples is 0 or less (%d). Setting to 1.", delaySamples);
         delaySamples = 1; // Minimum delay is 1 sample
    }

    reverbGain = gain;

    // Initialize delay line buffer
    try {
        delayLine.assign(delaySamples, 0.0f); // Allocate and fill with zeros
        writeIndex = 0;
        isInitialized = true;
        LOGI("Reverb initialized: sampleRate=%d, delayMs=%d, delaySamples=%d, gain=%f, bufferSize=%zu",
             sampleRate, delayMs, delaySamples, gain, delayLine.size());
        return 0; // Success
    } catch (const std::bad_alloc& e) {
        LOGE("Failed to allocate memory for delay line: %s", e.what());
        isInitialized = false; // Ensure state is correct on failure
        return -3; // Indicate allocation failure
    } catch (const std::exception& e) {
         LOGE("An unexpected error occurred during initialization: %s", e.what());
         isInitialized = false;
         return -4; // Indicate other failure
    }
}

extern "C" JNIEXPORT void JNICALL
Java_com_yourcompany_yourappname_ReverbNative_processBuffer( // Replace with your package name
    JNIEnv *env,
    jobject /* this */,
    jshortArray buffer,
    jint numSamples) {

    if (!isInitialized || delayLine.empty()) {
        // LOGW("Reverb not initialized or delay line is empty. Skipping processing.");
        return; // Cannot process if not initialized
    }

    if (numSamples <= 0) {
        return; // Nothing to process
    }

    // Get a pointer to the Java short array elements
    jshort *bufferPtr = env->GetShortArrayElements(buffer, NULL);
    if (bufferPtr == NULL) {
        LOGE("Failed to get short array elements");
        return; // Failed to get array elements
    }

    // Process each sample in the buffer
    for (int i = 0; i < numSamples; ++i) {
        // Convert input short sample to float
        float inputSample = shortToFloat(bufferPtr[i]);

        // Calculate read index (circular buffer)
        // readIndex is 'delaySamples' samples before the current writeIndex
        int readIndex = (writeIndex - delaySamples + delayLine.size()) % delayLine.size();
        // Ensure readIndex is non-negative
        if (readIndex < 0) readIndex += delayLine.size();


        // Get delayed sample from the delay line
        float delayedSample = delayLine[readIndex];

        // Simple Feedforward Comb Filter: output = input + gain * delayed_input
        // We are storing the *input* in the delay line, not the output.
        float outputSample = inputSample + reverbGain * delayedSample;

        // Store the current input sample in the delay line at the write index
        delayLine[writeIndex] = inputSample;

        // Advance the write index (circular buffer)
        writeIndex = (writeIndex + 1) % delayLine.size();

        // Convert output float sample back to short (with clipping)
        bufferPtr[i] = floatToShort(outputSample);
    }

    // Release the array elements.
    // JNI_COMMIT: Copy back changes to the original array.
    // 0: Copy back changes and free the copy if it was made.
    // JNI_ABORT: Don't copy back changes, free the copy.
    env->ReleaseShortArrayElements(buffer, bufferPtr, 0); // Use 0 to write changes back
}

extern "C" JNIEXPORT void JNICALL
Java_com_yourcompany_yourappname_ReverbNative_releaseReverb(
    JNIEnv *env,
    jobject /* this */) {

    if (!isInitialized) {
        // LOGW("Reverb not initialized. Nothing to release.");
        return;
    }

    LOGI("Releasing reverb resources");
    delayLine.clear(); // Frees the memory used by the vector
    delaySamples = 0;
    reverbGain = 0.0f;
    writeIndex = 0;
    isInitialized = false;
}
