**2. `MyVpnService.kt`**

```kotlin
package com.yourcompany.vpnfilterapp // Replace with your package name

import android.app.PendingIntent
import android.content.Intent
import android.net.VpnService
import android.os.ParcelFileDescriptor
import android.util.Log
import java.io.FileInputStream
import java.io.FileOutputStream
import java.io.IOException
import java.net.InetAddress
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.concurrent.atomic.AtomicBoolean

class MyVpnService : VpnService() {

    private val TAG = "MyVpnService"
    private var vpnInterface: ParcelFileDescriptor? = null
    private var packetReaderThread: Thread? = null
    private val running = AtomicBoolean(false)

    // --- Configuration ---
    // Define the list of destination IPs to block
    private val BLOCKED_DEST_IPS = setOf(
        "8.8.8.8", // Example: Google Public DNS
        "1.1.1.1", // Example: Cloudflare DNS
        "208.67.222.222" // Example: OpenDNS
        // Add more IPs as strings here
    )
    // ---------------------

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        Log.d(TAG, "VPN Service started")

        // Stop any previous running instance
        if (running.get()) {
            stopVpn()
        }

        running.set(true)

        // Configure the VPN interface
        val builder = Builder()
        builder.setSession("My IP Filter VPN")
        builder.addAddress("10.8.0.1", 24) // Virtual IP and subnet for the device
        builder.addRoute("0.0.0.0", 0)    // Route all traffic through the VPN
        // builder.addDnsServer("8.8.8.8") // Optional: Add a DNS server

        // Set up a notification or persistent status (required for foreground service)
        // In a real app, you'd show a persistent notification here.
        // For this simple example, we'll skip the full notification setup but
        // the service still needs to be started as foreground in a real app
        // on modern Android versions. Skipping for brevity in this example.

        try {
            vpnInterface = builder.establish()
            if (vpnInterface == null) {
                Log.e(TAG, "Failed to establish VPN interface")
                stopVpn()
                return START_NOT_NOT_STICKY
            }

            Log.d(TAG, "VPN Interface established")

            // Start the thread to read packets from the interface
            packetReaderThread = Thread { readPackets() }.apply { start() }

            return START_STICKY // Service should be restarted if killed
        } catch (e: Exception) {
            Log.e(TAG, "Error establishing VPN", e)
            stopVpn()
            return START_NOT_STICKY
        }
    }

    private fun readPackets() {
        val inputStream = FileInputStream(vpnInterface?.fileDescriptor)
        // Output stream is needed if you were implementing tunneling/proxying
        // val outputStream = FileOutputStream(vpnInterface?.fileDescriptor)

        val packetBuffer = ByteBuffer.allocate(32767).order(ByteOrder.BIG_ENDIAN) // Max IP packet size
        Log.d(TAG, "Packet reader thread started")

        while (running.get() && !Thread.currentThread().isInterrupted) {
            try {
                packetBuffer.clear()
                // Read packet from the VPN interface
                val length = inputStream.read(packetBuffer.array())

                if (length > 0) {
                    packetBuffer.limit(length)

                    // Parse destination IP
                    val destIp = getDestinationIp(packetBuffer)

                    if (destIp != null) {
                        if (BLOCKED_DEST_IPS.contains(destIp)) {
                            Log.i(TAG, "Blocked packet to: $destIp (Length: $length)")
                            // Do nothing - packet is dropped
                        } else {
                            // For a real VPN, you would now process/forward this packet.
                            // In this example, we just log that it wasn't blocked,
                            // but it will still fail as we don't forward it.
                            Log.v(TAG, "Allowed packet to: $destIp (Length: $length)")

                            // Example: If you were tunneling, you'd write to a socket here
                            // val protocol = getIpProtocol(packetBuffer)
                            // val sourceIp = getSourceIp(packetBuffer)
                            // ... handle TCP/UDP connections ...
                        }
                    } else {
                         Log.w(TAG, "Could not parse destination IP from packet")
                    }
                }
            } catch (e: IOException) {
                if (running.get()) {
                    Log.e(TAG, "Error reading packet", e)
                } else {
                    // Expected exception when stopping the service
                    Log.d(TAG, "Packet reader shutting down", e)
                }
                break
            } catch (e: Exception) {
                 Log.e(TAG, "Unexpected error in packet reader", e)
                 break
            }
        }
        Log.d(TAG, "Packet reader thread stopped")
    }

    // Parses the destination IP address from an IPv4 packet buffer
    private fun getDestinationIp(packet: ByteBuffer): String? {
        try {
            // Ensure buffer position is at the start of the packet
            packet.rewind()

            // Check minimum IP header length (20 bytes for IPv4)
            if (packet.limit() < 20) {
                Log.w(TAG, "Packet too short for IP header: ${packet.limit()} bytes")
                return null
            }

            // Read the first byte (Version and IHL)
            val versionIhl = packet.get(0).toInt()
            val version = (versionIhl shr 4) and 0x0F
            val ihl = versionIhl and 0x0F // IHL is in 32-bit words

            if (version != 4) {
                // Only handle IPv4 for this example
                // Log.v(TAG, "Ignoring non-IPv4 packet (Version: $version)")
                return null
            }

            val ipHeaderLength = ihl * 4 // Convert IHL to bytes

            // Destination IP is typically at offset 16 in IPv4 header
            if (packet.limit() < ipHeaderLength || ipHeaderLength < 20) {
                 Log.w(TAG, "Invalid IP header length: $ipHeaderLength bytes")
                 return null
            }

            val destIpBytes = ByteArray(4)
            packet.position(16) // Move buffer position to destination IP field
            packet.get(destIpBytes) // Read 4 bytes

            return InetAddress.getByAddress(destIpBytes).hostAddress

        } catch (e: Exception) {
            Log.e(TAG, "Error parsing destination IP", e)
            return null
        }
    }

    // Optional: Get protocol (TCP=6, UDP=17)
    private fun getIpProtocol(packet: ByteBuffer): Int? {
         try {
            packet.rewind()
            val versionIhl = packet.get(0).toInt()
            val version = (versionIhl shr 4) and 0x0F
            if (version != 4) return null
            val ihl = versionIhl and 0x0F
            val ipHeaderLength = ihl * 4
            if (packet.limit() < ipHeaderLength || ipHeaderLength < 10) return null // Need at least 10 bytes for protocol field
            return packet.get(9).toInt() and 0xFF // Protocol is at offset 9
         } catch (e: Exception) {
             Log.e(TAG, "Error parsing IP protocol", e)
             return null
         }
    }

    // Optional: Get Source IP
     private fun getSourceIp(packet: ByteBuffer): String? {
        try {
            packet.rewind()
            val versionIhl = packet.get(0).toInt()
            val version = (versionIhl shr 4) and 0x0F
            if (version != 4) return null
            val ihl = versionIhl and 0x0F
            val ipHeaderLength = ihl * 4
            if (packet.limit() < ipHeaderLength || ipHeaderLength < 12) return null // Need at least 12 bytes for source IP field

            val sourceIpBytes = ByteArray(4)
            packet.position(12) // Source IP is at offset 12
            packet.get(sourceIpBytes)

            return InetAddress.getByAddress(sourceIpBytes).hostAddress

        } catch (e: Exception) {
            Log.e(TAG, "Error parsing source IP", e)
            return null
        }
    }


    override fun onRevoke() {
        Log.d(TAG, "VPN revoked")
        stopVpn()
        super.onRevoke()
    }

    override fun onDestroy() {
        Log.d(TAG, "VPN Service destroyed")
        stopVpn()
        super.onDestroy()
    }

    private fun stopVpn() {
        Log.d(TAG, "Stopping VPN")
        running.set(false)
        packetReaderThread?.interrupt() // Interrupt the reading thread
        try {
            packetReaderThread?.join() // Wait for the thread to finish
        } catch (e: InterruptedException) {
            Log.e(TAG, "Interrupted while waiting for reader thread to join", e)
        }
        packetReaderThread = null

        try {
            vpnInterface?.close()
            Log.d(TAG, "VPN Interface closed")
        } catch (e: IOException) {
            Log.e(TAG, "Error closing VPN interface", e)
        }
        vpnInterface = null
    }
}
```

