*Note: Handling client certificates (`client-certificate-data` and `client-key-data` in kubeconfig) requires configuring a `KeyManagerFactory` in the `SSLContext`, which is more involved.*

**Step 2: Implement the Log Reading Method**

This method will build the request, add headers, send it, and process the response.

```java
// ... (inside the KubernetesLogReader class from Step 1)

    /**
     * Reads logs for a specific pod and container.
     *
     * @param namespace The pod's namespace.
     * @param podName The pod's name.
     * @param containerName The container's name (optional, can be null).
     * @param follow If true, streams logs. If false, gets current logs.
     * @return If follow is true, returns an InputStream. If follow is false, returns the log String.
     * @throws IOException If a network or API error occurs.
     * @throws InterruptedException If the request is interrupted.
     * @throws IllegalArgumentException If required parameters are missing.
     */
    public Object readPodLogs(String namespace, String podName, String containerName, boolean follow)
            throws IOException, InterruptedException {

        if (namespace == null || namespace.trim().isEmpty()) {
            throw new IllegalArgumentException("Namespace cannot be null or empty.");
        }
        if (podName == null || podName.trim().isEmpty()) {
            throw new IllegalArgumentException("Pod name cannot be null or empty.");
        }

        // Build the API endpoint URL
        StringBuilder urlBuilder = new StringBuilder();
        urlBuilder.append(apiServerUrl)
                  .append("/api/v1/namespaces/")
                  .append(namespace)
                  .append("/pods/")
                  .append(podName)
                  .append("/log");

        // Add query parameters
        urlBuilder.append("?"); // Start query string

        boolean firstParam = true;

        if (containerName != null && !containerName.trim().isEmpty()) {
            urlBuilder.append("container=").append(containerName);
            firstParam = false;
        }

        if (follow) {
            if (!firstParam) urlBuilder.append("&");
            urlBuilder.append("follow=true");
            firstParam = false;
        } else {
            // You might add other non-follow parameters like tailLines, sinceSeconds here
            // Example:
            // if (!firstParam) urlBuilder.append("&");
            // urlBuilder.append("tailLines=100");
            // firstParam = false;
        }

        URI uri = URI.create(urlBuilder.toString());
        System.out.println("Requesting logs from: " + uri);

        // Build the HttpRequest
        HttpRequest request = HttpRequest.newBuilder()
                .uri(uri)
                .header("Authorization", "Bearer " + authToken) // Add the authentication header
                .GET() // Use GET method
                .build();

        // Send the request
        if (follow) {
            // For follow=true, we expect a continuous stream
            HttpResponse<InputStream> response = httpClient.send(request, HttpResponse.BodyHandlers.ofInputStream());

            // Check response status
            if (response.statusCode() != 200) {
                String errorBody = new String(response.body().readAllBytes()); // Read error body if not 200
                throw new IOException("Failed to get pod logs. Status code: " + response.statusCode() + ", Body: " + errorBody);
            }

            System.out.println("Streaming logs...");
            return response.body(); // Return the InputStream for streaming

        } else {
            // For follow=false, get the entire response body as a string
            HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

            // Check response status
            if (response.statusCode() != 200) {
                throw new IOException("Failed to get pod logs. Status code: " + response.statusCode() + ", Body: " + response.body());
            }

            System.out.println("Successfully fetched logs.");
            return response.body(); // Return the log string
        }
    }

    // Add methods for other log parameters if needed, e.g.,
    // public String readPodLogs(String namespace, String podName, String containerName, int tailLines) { ... }
}
