Okay, let's illustrate the Strategy Pattern using a fun banking app scenario where different account types earn *transaction bonuses* (like points or cashback) based on different rules.

**Scenario:**

We have different types of bank accounts (Basic, Premium, SuperSaver). Each account type has a different strategy for calculating the bonus earned on a deposit or withdrawal.

*   **Basic Account:** No bonus.
*   **Premium Account:** Earns 1% of the transaction amount as points.
*   **SuperSaver Account:** Earns a tiered bonus: 0.5% for transactions under $100, and 1.5% for transactions $100 or more.

The core `BankAccount` logic (depositing, withdrawing, managing balance) should *not* need to know the specific rules for each bonus type. This is where the Strategy Pattern comes in.

**Strategy Pattern Components:**

1.  **Strategy Interface (Implicit in JS):** Defines the common method(s) that all concrete strategies must implement (`calculateBonus` in this case).
2.  **Concrete Strategies:** Implement the strategy interface with specific algorithms (e.g., `NoBonusStrategy`, `PercentageBonusStrategy`, `TieredBonusStrategy`).
3.  **Context:** The class that holds a reference to a strategy object and delegates the task (bonus calculation) to the strategy (`BankAccount` in this case).

Here's the JavaScript code:

```javascript
// 1. Strategy Interface (Implicit)
// All strategy objects should have a method like:
// calculateBonus(amount: number): number;


// 2. Concrete Strategies

/**
 * Strategy: No bonus earned on transactions.
 */
const noBonusStrategy = {
  calculateBonus(amount) {
    console.log("  [Bonus Strategy] Basic: No bonus applied.");
    return 0; // Always returns 0 points
  }
};

/**
 * Strategy: Earns a fixed percentage of the transaction amount.
 */
const percentageBonusStrategy = {
  percentage: 0.01, // 1%
  calculateBonus(amount) {
    const bonus = amount * this.percentage;
    console.log(`  [Bonus Strategy] Premium: Earned ${bonus.toFixed(2)} points (${(this.percentage * 100).toFixed(1)}% of $${amount.toFixed(2)}).`);
    return bonus;
  }
};

/**
 * Strategy: Earns a bonus based on tiers of the transaction amount.
 */
const tieredBonusStrategy = {
  lowThreshold: 100,
  lowRate: 0.005, // 0.5% below threshold
  highRate: 0.015, // 1.5% at or above threshold

  calculateBonus(amount) {
    let bonus = 0;
    if (amount < this.lowThreshold) {
      bonus = amount * this.lowRate;
      console.log(`  [Bonus Strategy] SuperSaver: Earned ${bonus.toFixed(2)} points (${(this.lowRate * 100).toFixed(1)}% for < $${this.lowThreshold}) on $${amount.toFixed(2)}.`);
    } else {
      bonus = amount * this.highRate;
      console.log(`  [Bonus Strategy] SuperSaver: Earned ${bonus.toFixed(2)} points (${(this.highRate * 100).toFixed(1)}% for >= $${this.lowThreshold}) on $${amount.toFixed(2)}.`);
    }
    return bonus;
  }
};


// 3. Context

/**
 * The BankAccount class (Context) that uses a Bonus Strategy.
 */
class BankAccount {
  constructor(accountNumber, initialBalance, bonusStrategy) {
    this.accountNumber = accountNumber;
    this.balance = initialBalance;
    this.pointsBalance = 0; // Keep track of bonus points
    this.bonusStrategy = bonusStrategy; // Holds the current strategy object
    console.log(`\n--- Account ${this.accountNumber} Created ---`);
    console.log(`Initial Balance: $${this.balance.toFixed(2)}`);
    console.log(`Assigned Strategy: ${bonusStrategy.constructor ? bonusStrategy.constructor.name : 'Custom Object'}`); // Show strategy type
    console.log('----------------------------');
  }

  // Method to change the strategy at runtime
  setBonusStrategy(newStrategy) {
    this.bonusStrategy = newStrategy;
    console.log(`\n--- Strategy Updated for Account ${this.accountNumber} ---`);
    console.log(`New Strategy: ${newStrategy.constructor ? newStrategy.constructor.name : 'Custom Object'}`);
    console.log('----------------------------');
  }

  deposit(amount) {
    if (amount <= 0) {
      console.log(`[Account ${this.accountNumber}] Deposit amount must be positive.`);
      return;
    }
    this.balance += amount;
    console.log(`[Account ${this.accountNumber}] Deposited $${amount.toFixed(2)}. New Balance: $${this.balance.toFixed(2)}.`);

    // Delegate the bonus calculation to the current strategy
    const earnedPoints = this.bonusStrategy.calculateBonus(amount);
    this.pointsBalance += earnedPoints;
    console.log(`[Account ${this.accountNumber}] Total Points: ${this.pointsBalance.toFixed(2)}.`);
  }

  withdraw(amount) {
     if (amount <= 0) {
       console.log(`[Account ${this.accountNumber}] Withdrawal amount must be positive.`);
       return;
     }
     if (amount > this.balance) {
       console.log(`[Account ${this.accountNumber}] Insufficient funds for withdrawal of $${amount.toFixed(2)}.`);
       return;
     }
     this.balance -= amount;
     console.log(`[Account ${this.accountNumber}] Withdrew $${amount.toFixed(2)}. New Balance: $${this.balance.toFixed(2)}.`);

     // Delegate the bonus calculation to the current strategy
     // Note: Strategies can decide if withdrawals earn points or not (e.g., NoBonusStrategy returns 0)
     const earnedPoints = this.bonusStrategy.calculateBonus(amount);
     this.pointsBalance += earnedPoints;
     console.log(`[Account ${this.accountNumber}] Total Points: ${this.pointsBalance.toFixed(2)}.`);
  }

  getAccountInfo() {
     console.log(`\n--- Account Summary ${this.accountNumber} ---`);
     console.log(`Balance: $${this.balance.toFixed(2)}`);
     console.log(`Points Balance: ${this.pointsBalance.toFixed(2)}`);
     console.log(`Current Strategy: ${this.bonusStrategy.constructor ? this.bonusStrategy.constructor.name : 'Custom Object'}`);
     console.log('----------------------------');
  }
}


// --- Demonstration ---

// Create different accounts with different strategies
const basicAccount = new BankAccount("ACC-001", 500, noBonusStrategy);
const premiumAccount = new BankAccount("ACC-002", 2000, percentageBonusStrategy);
const superSaverAccount = new BankAccount("ACC-003", 10000, tieredBonusStrategy);

console.log("\n--- Performing Transactions ---");

// Transactions on Basic Account (No Bonus)
basicAccount.deposit(100);
basicAccount.withdraw(50);

// Transactions on Premium Account (1% Bonus)
premiumAccount.deposit(500);
premiumAccount.withdraw(100); // Withdrawals also earn bonus in this strategy

// Transactions on SuperSaver Account (Tiered Bonus)
superSaverAccount.deposit(80);  // Should earn 0.5%
superSaverAccount.deposit(150); // Should earn 1.5%
superSaverAccount.withdraw(60); // Should earn 0.5%

console.log("\n--- Account Status After Transactions ---");
basicAccount.getAccountInfo();
premiumAccount.getAccountInfo();
superSaverAccount.getAccountInfo();

console.log("\n--- Changing Strategy for Account ACC-001 ---");
// Upgrade the basic account to a premium account strategy
basicAccount.setBonusStrategy(percentageBonusStrategy);

console.log("\n--- Performing More Transactions on Upgraded Account ---");
basicAccount.deposit(200); // Now this should earn a bonus
basicAccount.withdraw(75);

console.log("\n--- Final Status of Upgraded Account ---");
basicAccount.getAccountInfo();
```

**Explanation:**

1.  **Strategies (`noBonusStrategy`, `percentageBonusStrategy`, `tieredBonusStrategy`):** These are simple JavaScript objects (or could be classes) that encapsulate the specific bonus calculation logic. They all implement the same "interface" by having a `calculateBonus` method that takes an amount and returns the calculated bonus.
2.  **Context (`BankAccount` Class):** This class represents the bank account.
    *   It *doesn't* contain `if/else` or `switch` statements to figure out *how* to calculate the bonus based on account type.
    *   Instead, it holds a reference (`this.bonusStrategy`) to one of the strategy objects.
    *   When a transaction happens (`deposit`, `withdraw`), it simply calls `this.bonusStrategy.calculateBonus(amount)`. It delegates the "how" to the currently assigned strategy object.
    *   The `setBonusStrategy` method shows how the strategy can be changed at runtime, allowing an account to "upgrade" its bonus earning rules without changing the core `BankAccount` class logic.
3.  **Demonstration:** We create instances of `BankAccount`, injecting different strategy objects into their constructors. Then, we perform transactions and observe how the bonus calculation (and the points earned) changes depending on the strategy assigned to each account. We also show how the strategy can be swapped out later.

**Benefits of using Strategy Pattern here:**

*   **Flexibility:** Easily add new bonus strategies (e.g., "Fixed Bonus per Month", "Bonus for Large Transactions") without modifying the `BankAccount` class.
*   **Maintainability:** The bonus calculation logic is isolated in separate strategy objects, making them easier to understand, test, and modify.
*   **Avoids Conditionals:** The `BankAccount` class doesn't need complex `if/else` logic based on account type to determine the bonus rule.
*   **Runtime Behavior Change:** The strategy can be changed dynamically for an object (like upgrading an account), altering its behavior without changing its class.

Okay, let's build a simple To-Do List application using the PERN stack (PostgreSQL, Express, React, Node.js).

We'll create three main parts:

1.  **Database (PostgreSQL):** A table to store the to-do items.
2.  **Backend (Node.js + Express):** An API to interact with the database (CRUD operations).
3.  **Frontend (React):** A user interface to display, add, edit, and delete to-do items.

---

**1. Database Setup (PostgreSQL)**

First, make sure you have PostgreSQL installed and running. You can use a command-line client (`psql`) or a GUI tool like pgAdmin to set up your database.

Create a database (e.g., `perntodo`):

```sql
CREATE DATABASE perntodo;
```

Connect to the database and create the `todos` table:

```sql
-- Connect to your database first, e.g., \c perntodo
CREATE TABLE todos (
    todo_id SERIAL PRIMARY KEY,
    description VARCHAR(255) NOT NULL,
    is_done BOOLEAN DEFAULT FALSE
);
```

---

**2. Backend (Node.js + Express)**

This will be our API server.

*   **Project Setup:**
    Create a new directory for your backend (e.g., `backend`).
    Open your terminal in the `backend` directory and run:
    ```bash
    npm init -y
    npm install express pg cors dotenv
    ```

*   **Environment Variables (`.env`):**
    Create a file named `.env` in the `backend` directory to store your database credentials. Replace the placeholders with your actual details.

    ```env
    PGUSER=your_db_username
    PGHOST=your_db_host # e.g., localhost
    PGDATABASE=perntodo
    PGPASSWORD=your_db_password
    PGPORT=5432 # Default PostgreSQL port
    PORT=5000 # Port for the backend server
    ```

*   **Server Code (`index.js`):**
    Create a file named `index.js` in the `backend` directory.

    ```javascript
    require('dotenv').config(); // Load environment variables from .env file
    const express = require('express');
    const cors = require('cors');
    const { Pool } = require('pg');

    const app = express();
    const PORT = process.env.PORT || 5000; // Use port from .env or default to 5000

    // Middleware
    app.use(cors()); // Allows cross-origin requests from the frontend
    app.use(express.json()); // Parses incoming JSON requests

    // PostgreSQL Connection Pool
    const pool = new Pool({
        user: process.env.PGUSER,
        host: process.env.PGHOST,
        database: process.env.PGDATABASE,
        password: process.env.PGPASSWORD,
        port: process.env.PGPORT,
    });

    // --- ROUTES ---

    // Create a Todo
    app.post('/todos', async (req, res) => {
        try {
            const { description } = req.body;
            if (!description) {
                return res.status(400).json({ error: 'Description is required' });
            }
            const newTodo = await pool.query(
                'INSERT INTO todos (description) VALUES ($1) RETURNING *',
                [description]
            );
            res.json(newTodo.rows[0]);
        } catch (err) {
            console.error(err.message);
            res.status(500).send('Server Error');
        }
    });

    // Get All Todos
    app.get('/todos', async (req, res) => {
        try {
            const allTodos = await pool.query('SELECT * FROM todos ORDER BY todo_id ASC');
            res.json(allTodos.rows);
        } catch (err) {
            console.error(err.message);
            res.status(500).send('Server Error');
        }
    });

    // Get a Single Todo
    app.get('/todos/:id', async (req, res) => {
        try {
            const { id } = req.params;
            const todo = await pool.query('SELECT * FROM todos WHERE todo_id = $1', [id]);

            if (todo.rows.length === 0) {
                return res.status(404).json({ error: 'Todo not found' });
            }

            res.json(todo.rows[0]);
        } catch (err) {
            console.error(err.message);
            res.status(500).send('Server Error');
        }
    });

    // Update a Todo
    app.put('/todos/:id', async (req, res) => {
        try {
            const { id } = req.params;
            const { description, is_done } = req.body; // Expecting both fields for update

            if (description === undefined && is_done === undefined) {
                 return res.status(400).json({ error: 'No fields provided for update' });
            }

            let query = 'UPDATE todos SET ';
            const values = [];
            const setParts = [];
            let paramIndex = 1;

            if (description !== undefined) {
                setParts.push(`description = $${paramIndex++}`);
                values.push(description);
            }
            if (is_done !== undefined) {
                setParts.push(`is_done = $${paramIndex++}`);
                values.push(is_done);
            }

            query += setParts.join(', ') + ` WHERE todo_id = $${paramIndex++} RETURNING *`;
            values.push(id);

            const updateTodo = await pool.query(query, values);

            if (updateTodo.rows.length === 0) {
                 return res.status(404).json({ error: 'Todo not found' });
            }

            res.json(updateTodo.rows[0]);

        } catch (err) {
            console.error(err.message);
            res.status(500).send('Server Error');
        }
    });


    // Delete a Todo
    app.delete('/todos/:id', async (req, res) => {
        try {
            const { id } = req.params;
            const deleteTodo = await pool.query('DELETE FROM todos WHERE todo_id = $1 RETURNING *', [id]);

             if (deleteTodo.rows.length === 0) {
                 return res.status(404).json({ error: 'Todo not found' });
            }

            res.json({ message: 'Todo was deleted', deletedTodo: deleteTodo.rows[0] });
        } catch (err) {
            console.error(err.message);
            res.status(500).send('Server Error');
        }
    });


    // Start Server
    app.listen(PORT, () => {
        console.log(`Server is running on port ${PORT}`);
    });
    ```

*   **Run Backend:**
    In the `backend` directory, run:
    ```bash
    node index.js
    ```
    The server should start on `http://localhost:5000`.

---

**3. Frontend (React)**

This will be our user interface.

*   **Project Setup:**
    Create a new directory for your frontend (e.g., `frontend`).
    Open your terminal *outside* the `backend` directory and run:
    ```bash
    npx create-react-app frontend
    cd frontend
    npm install axios # Or use built-in fetch
    ```

*   **Environment Variables (`.env`):**
    Create a file named `.env` in the `frontend` directory. This tells React where your backend API is.

    ```env
    REACT_APP_BACKEND_URL=http://localhost:5000
    ```

*   **Components:**
    We'll create a few simple components:
    *   `App.js`: Main component, fetches todos, manages state.
    *   `AddTodoForm.js`: Form to add new todos.
    *   `TodoList.js`: Displays the list of todos.
    *   `TodoItem.js`: Displays a single todo, handles edit/delete/toggle done.

    **`src/App.js`:**

    ```javascript
    import React, { useState, useEffect } from 'react';
    import axios from 'axios';
    import AddTodoForm from './AddTodoForm';
    import TodoList from './TodoList';
    import './App.css'; // Basic styling

    const API_URL = process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000';

    function App() {
      const [todos, setTodos] = useState([]);

      // Fetch all todos
      const fetchTodos = async () => {
        try {
          const response = await axios.get(`${API_URL}/todos`);
          setTodos(response.data);
        } catch (error) {
          console.error('Error fetching todos:', error);
        }
      };

      // Add a new todo
      const addTodo = async (description) => {
        try {
          const response = await axios.post(`${API_URL}/todos`, { description });
          // Add the newly created todo to the state
          setTodos([...todos, response.data]);
        } catch (error) {
          console.error('Error adding todo:', error);
        }
      };

       // Update a todo (description or is_done)
       const updateTodo = async (id, updatedFields) => {
         try {
           const response = await axios.put(`${API_URL}/todos/${id}`, updatedFields);
           // Update the todo in the state
           setTodos(todos.map(todo =>
             todo.todo_id === id ? response.data : todo
           ));
         } catch (error) {
           console.error('Error updating todo:', error);
         }
       };

      // Delete a todo
      const deleteTodo = async (id) => {
        try {
          await axios.delete(`${API_URL}/todos/${id}`);
          // Remove the deleted todo from the state
          setTodos(todos.filter(todo => todo.todo_id !== id));
        } catch (error) {
          console.error('Error deleting todo:', error);
        }
      };

      // Fetch todos on component mount
      useEffect(() => {
        fetchTodos();
      }, []); // Empty dependency array means this runs once on mount

      return (
        <div className="App">
          <h1>PERN Stack Todo List</h1>
          <AddTodoForm onAdd={addTodo} />
          <TodoList
            todos={todos}
            onDelete={deleteTodo}
            onUpdate={updateTodo} // Pass update function
          />
        </div>
      );
    }

    export default App;
    ```

    **`src/AddTodoForm.js`:**

    ```javascript
    import React, { useState } from 'react';
