            />
          ))}
        </ul>
      );
    }

    export default TodoList;
    ```

    **`src/TodoItem.js`:**

    ```javascript
    import React, { useState } from 'react';
    import './TodoItem.css'; // Basic styling

    function TodoItem({ todo, onDelete, onUpdate }) {
      const [isEditing, setIsEditing] = useState(false);
      const [newDescription, setNewDescription] = useState(todo.description);

      const handleUpdateDescription = () => {
        if (!newDescription.trim()) {
           alert('Description cannot be empty');
           return;
        }
        // Send both description and current is_done status
        onUpdate(todo.todo_id, { description: newDescription, is_done: todo.is_done });
        setIsEditing(false); // Exit edit mode
      };

      const handleToggleDone = () => {
        // Toggle is_done status and send it along with current description
        onUpdate(todo.todo_id, { description: todo.description, is_done: !todo.is_done });
      };

      return (
        <li className={`todo-item ${todo.is_done ? 'completed' : ''}`}>
          <input
            type="checkbox"
            checked={todo.is_done}
            onChange={handleToggleDone}
          />
          {isEditing ? (
            <input
              type="text"
              value={newDescription}
              onChange={(e) => setNewDescription(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter') {
                  handleUpdateDescription();
                }
              }}
              autoFocus // Automatically focus the input when editing starts
            />
          ) : (
            <span className="todo-description">{todo.description}</span>
          )}

          <div className="todo-actions">
            {isEditing ? (
              <button onClick={handleUpdateDescription}>Save</button>
            ) : (
              <button onClick={() => setIsEditing(true)}>Edit</button>
            )}
            <button onClick={() => onDelete(todo.todo_id)}>Delete</button>
          </div>
        </li>
      );
    }

    export default TodoItem;
    ```

