**3. `script.js`**

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('spriteCanvas');
    const ctx = canvas.getContext('2d');

    const colorPicker = document.getElementById('colorPicker');
    const spriteWidthInput = document.getElementById('spriteWidth');
    const spriteHeightInput = document.getElementById('spriteHeight');
    const resizeButton = document.getElementById('resizeSprite');
    const clearButton = document.getElementById('clearCanvas');
    const saveJsonButton = document.getElementById('saveJson');
    const savePngButton = document.getElementById('savePng');

    let spriteWidth = parseInt(spriteWidthInput.value);
    let spriteHeight = parseInt(spriteHeightInput.value);
    const canvasSize = 512; // Fixed size for the canvas display area
    let pixelSize = canvasSize / Math.max(spriteWidth, spriteHeight); // Size of each pixel on the canvas

    // 2D array to store sprite data (colors)
    // Use a color string (e.g., hex or rgba) for each pixel.
    // null or 'rgba(0,0,0,0)' can represent transparency.
    let spriteData = [];

    // --- Initialization ---

    function createEmptySpriteData(width, height) {
        const data = [];
        for (let y = 0; y < height; y++) {
            data[y] = [];
            for (let x = 0; x < width; x++) {
                data[y][x] = '#ffffff'; // Default color (white)
                // Use 'rgba(0,0,0,0)' for transparent default
            }
        }
        return data;
    }

    function updateCanvasDimensions() {
        // Set the internal canvas drawing surface size
        canvas.width = canvasSize;
        canvas.height = canvasSize;
        // Calculate the size of each sprite pixel on the canvas
        pixelSize = canvasSize / Math.max(spriteWidth, spriteHeight);

         // Adjust canvas styling if needed (though CSS handles display size)
         // canvas.style.width = `${canvasSize}px`;
         // canvas.style.height = `${canvasSize}px`;
    }


    function drawSprite() {
        // Clear the entire canvas
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw the pixels
        for (let y = 0; y < spriteHeight; y++) {
            for (let x = 0; x < spriteWidth; x++) {
                const color = spriteData[y][x];
                if (color) { // Only draw if a color is set (not null/transparent)
                    ctx.fillStyle = color;
                    // Draw the pixel rectangle
                    ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
                }
            }
        }

        // Draw the grid lines
        ctx.strokeStyle = '#eeeeee'; // Light grey grid lines
        ctx.lineWidth = 1; // Grid line thickness

        // Draw vertical lines
        for (let x = 0; x <= spriteWidth; x++) {
            ctx.beginPath();
            ctx.moveTo(x * pixelSize, 0);
            ctx.lineTo(x * pixelSize, spriteHeight * pixelSize); // Only draw grid within the sprite area
            ctx.stroke();
        }

        // Draw horizontal lines
        for (let y = 0; y <= spriteHeight; y++) {
            ctx.beginPath();
            ctx.moveTo(0, y * pixelSize);
            ctx.lineTo(spriteWidth * pixelSize, y * pixelSize); // Only draw grid within the sprite area
            ctx.stroke();
        }
    }

    function initEditor() {
        spriteData = createEmptySpriteData(spriteWidth, spriteHeight);
        updateCanvasDimensions();
        drawSprite();
    }

    // --- Event Listeners ---

    // Handle pixel drawing on click
    canvas.addEventListener('mousedown', (event) => {
        const rect = canvas.getBoundingClientRect();
        const scaleX = canvas.width / rect.width;    // Relationship bitmap vs. layout size
        const scaleY = canvas.height / rect.height;  // Relationship bitmap vs. layout size

        // Get mouse position relative to the canvas's internal drawing surface
        const mouseX = (event.clientX - rect.left) * scaleX;
        const mouseY = (event.clientY - rect.top) * scaleY;

        // Calculate which sprite pixel was clicked
        const pixelX = Math.floor(mouseX / pixelSize);
        const pixelY = Math.floor(mouseY / pixelSize);

        // Check if within bounds
        if (pixelX >= 0 && pixelX < spriteWidth && pixelY >= 0 && pixelY < spriteHeight) {
            const selectedColor = colorPicker.value;
            spriteData[pixelY][pixelX] = selectedColor;
            drawSprite(); // Redraw the canvas
        }
    });

    // Handle resize button click
    resizeButton.addEventListener('click', () => {
        const newWidth = parseInt(spriteWidthInput.value);
        const newHeight = parseInt(spriteHeightInput.value);

        if (isNaN(newWidth) || isNaN(newHeight) || newWidth < 1 || newHeight < 1) {
             alert("Please enter valid dimensions (minimum 1x1).");
             // Reset inputs to current valid size
             spriteWidthInput.value = spriteWidth;
             spriteHeightInput.value = spriteHeight;
             return;
        }

        spriteWidth = newWidth;
        spriteHeight = newHeight;
        initEditor(); // Re-initialize with new size (clears existing data)
    });

     // Handle clear button click
    clearButton.addEventListener('click', () => {
         initEditor(); // Re-initialize with current size (clears existing data)
    });


    // Handle save JSON button click
    saveJsonButton.addEventListener('click', () => {
        const jsonData = JSON.stringify(spriteData);
        const blob = new Blob([jsonData], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'sprite.json';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url); // Clean up
    });

     // Handle save PNG button click
    savePngButton.addEventListener('click', () => {
        // Create a temporary canvas to draw the sprite at its actual pixel resolution
        const tempCanvas = document.createElement('canvas');
        const tempCtx = tempCanvas.getContext('2d');

        tempCanvas.width = spriteWidth;
        tempCanvas.height = spriteHeight;

        // Draw the sprite data onto the temporary canvas, one pixel per canvas pixel
        for (let y = 0; y < spriteHeight; y++) {
            for (let x = 0; x < spriteWidth; x++) {
                const color = spriteData[y][x];
                 if (color) {
                    tempCtx.fillStyle = color;
                    tempCtx.fillRect(x, y, 1, 1);
                 } else {
                    // Explicitly draw transparent or white if needed for background
                    // tempCtx.clearRect(x, y, 1, 1); // Clears to transparent
                    // tempCtx.fillStyle = '#ffffff'; // Draw white background
                    // tempCtx.fillRect(x, y, 1, 1);
                 }
            }
        }

        // Get the data URL from the temporary canvas
        const dataURL = tempCanvas.toDataURL('image/png');

        // Create a download link
        const a = document.createElement('a');
        a.href = dataURL;
        a.download = 'sprite.png';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        // No need to revokeObjectURL for data URLs
    });


    // --- Initial Setup ---
    initEditor();

});
```

**How to Use:**

1.  Save the three code blocks above as `index.html`, `style.css`, and `script.js` in the same folder.
2.  Open `index.html` in your web browser.

**Explanation:**

1.  **HTML (`index.html`):** Sets up the basic page structure. It includes:
    *   A `<canvas>` element where the sprite will be drawn.
    *   Input elements (`<input type="color">`, `<input type="number">`) for selecting the color and setting dimensions.
    *   Buttons for resizing, clearing, and saving.
    *   Links the CSS and JavaScript files.
2.  **CSS (`style.css`):** Provides basic styling to make the editor look presentable. It centers the container, styles the controls, and adds a simple border and optional checkerboard background to the canvas area (to help visualize transparency if you use `rgba` colors).
3.  **JavaScript (`script.js`):** This is the core logic.
    *   **DOM References:** Gets references to all necessary HTML elements.
    *   **Variables:**
        *   `canvas`, `ctx`: The canvas element and its 2D rendering context.
        *   `spriteWidth`, `spriteHeight`: The current dimensions of the sprite in pixels.
        *   `canvasSize`: The fixed display size of the canvas on screen (e.g., 512x512 pixels).
        *   `pixelSize`: Calculated size (in canvas pixels) of each sprite pixel on the canvas. This scales the sprite to fit the `canvasSize`.
        *   `spriteData`: A 2D array (`spriteData[y][x]`) storing the color of each sprite pixel.
    *   **`createEmptySpriteData(width, height)`:** A helper function to create a new 2D array filled with a default color (currently white).
    *   **`updateCanvasDimensions()`:** Sets the internal `width` and `height` attributes of the canvas and recalculates `pixelSize`.
    *   **`drawSprite()`:** The main drawing function.
        *   Clears the canvas.
        *   Loops through the `spriteData` array.
        *   For each pixel with a color, it sets `ctx.fillStyle` and draws a rectangle using `ctx.fillRect` at the correct scaled position (`x * pixelSize`, `y * pixelSize`).
        *   Draws a grid on top using `ctx.strokeStyle`, `ctx.lineWidth`, `ctx.beginPath`, `ctx.moveTo`, `ctx.lineTo`, and `ctx.stroke`.
    *   **`initEditor()`:** Sets up the initial state: creates the `spriteData`, updates canvas dimensions, and draws the initial empty sprite. Called when the page loads and when resizing.
    *   **Event Listeners:**
        *   **Canvas `mousedown`:**
            *   Calculates the mouse position relative to the canvas.
            *   Calculates which sprite pixel (`pixelX`, `pixelY`) was clicked based on the mouse position and `pixelSize`.
            *   Checks if the click is within the sprite bounds.
            *   Gets the color from the color picker.
            *   Updates the `spriteData` array at the clicked location.
            *   Calls `drawSprite()` to update the display.
        *   **Resize Button `click`:**
            *   Reads the new dimensions from the number inputs.
            *   Basic validation.
            *   Updates `spriteWidth` and `spriteHeight`.
            *   Calls `initEditor()` which creates a *new* empty `spriteData` array and redraws. (Note: this clears the old sprite).
        *   **Clear Button `click`:** Calls `initEditor()` to clear the canvas using the current dimensions.
        *   **Save JSON Button `click`:**
            *   Converts the `spriteData` array to a JSON string using `JSON.stringify()`.
            *   Creates a `Blob` containing the JSON data.
            *   Creates a temporary `<a>` element, sets its `href` to a URL created from the Blob (`URL.createObjectURL`), sets the `download` attribute for the filename, and programmatically clicks it to trigger the download.
            *   Cleans up the temporary URL.
        *   **Save PNG Button `click`:**
            *   Creates a *temporary* canvas in memory.
            *   Sets its dimensions to the actual `spriteWidth` and `spriteHeight` (1 canvas pixel per sprite pixel).
            *   Draws the `spriteData` onto this temporary canvas at a 1:1 scale.
            *   Gets a data URL representing the image using `tempCanvas.toDataURL('image/png')`.
            *   Uses a similar `<a>` element trick as the JSON save to download the image.

