Okay, let's design a data-driven `Action` class based on configuration.

The core idea is that an `Action` isn't hardcoded logic, but rather a sequence of *effects*, where each effect modifies a character's attribute based on some calculated value. The "DSL" or configuration format will define these effects and how values are calculated.

Here's a possible structure for the configuration:

An **Action** is a list of **Effects**.
An **Effect** is a dictionary specifying:
*   `"target"`: Which character is affected ("actor" or "target").
*   `"attribute"`: Which attribute to modify (e.g., "hp", "damage").
*   `"operation"`: How to modify the attribute ("add", "subtract", "set", "multiply", "divide").
*   `"value"`: How to calculate the value used in the operation. This can be a simple number or a more complex structure.
*   `"save_result_as"` (optional): A name to save the actual *change* made by this effect (e.g., damage dealt) into a temporary context, so later effects can reference it.

A **Value** calculation can be represented by a dictionary with a `"type"` key:
*   `{"type": "literal", "value": N}`: A fixed number N.
*   `{"type": "attribute", "source": "actor" | "target", "attribute": "name"}`: Get the value of an attribute from the actor or target.
*   `{"type": "operation", "op": "+" | "-" | "*" | "/", "operands": [value_config1, value_config2, ...]}`: Perform an arithmetic operation on the results of calculating other values.
*   `{"type": "result_of_name", "name": "saved_name"}`: Get a value that was saved by a previous effect using `"save_result_as"`.

Let's implement this.

```python
import math

class Character:
    """A simple character with basic attributes."""
    def __init__(self, char_data):
        self.name = char_data.get("name", "Unnamed")
        self.max_hp = char_data.get("max_hp", 100) # Added max_hp for healing limits
        self.hp = char_data.get("hp", self.max_hp)
        self.damage = char_data.get("damage", 10)
        # Ensure HP doesn't exceed max_hp on creation
        self.hp = min(self.hp, self.max_hp)

    def __str__(self):
        return f"{self.name} (HP: {self.hp}/{self.max_hp}, Damage: {self.damage})"

    def __repr__(self):
        return self.__str__()

    def take_damage(self, amount):
        """Applies damage, ensuring HP doesn't go below zero."""
        if amount < 0:
             # Taking negative damage is healing
             return self.heal(abs(amount))

        old_hp = self.hp
        self.hp -= amount
        self.hp = max(0, self.hp) # HP cannot go below 0
        actual_change = self.hp - old_hp # This will be negative or zero
        return abs(actual_change) # Return positive damage dealt

    def heal(self, amount):
        """Applies healing, ensuring HP doesn't exceed max_hp."""
        if amount < 0:
            # Healing negative amount is taking damage
            return self.take_damage(abs(amount))

        old_hp = self.hp
        self.hp += amount
        self.hp = min(self.hp, self.max_hp) # HP cannot exceed max_hp
        actual_change = self.hp - old_hp # This will be positive or zero
        return actual_change # Return positive heal amount

    # Could add other methods for attribute changes if needed, or handle generically
    def set_attribute(self, attribute_name, value):
        """Generic method to set an attribute."""
        if hasattr(self, attribute_name):
            setattr(self, attribute_name, value)
        else:
            print(f"Warning: Character {self.name} does not have attribute '{attribute_name}'") # Or raise error

    def modify_attribute(self, attribute_name, operation, value):
        """Generic method to modify an attribute based on operation."""
        if not hasattr(self, attribute_name):
             print(f"Warning: Character {self.name} does not have attribute '{attribute_name}'. Cannot apply {operation}.")
             return 0 # Return 0 change

        old_value = getattr(self, attribute_name)
        new_value = old_value # Start with old value

        # --- Apply Operation ---
        try:
            if operation == "add":
                new_value = old_value + value
            elif operation == "subtract":
                new_value = old_value - value
            elif operation == "set":
                 new_value = value
            elif operation == "multiply":
                 new_value = old_value * value
            elif operation == "divide":
                 if value == 0:
                      print(f"Warning: Division by zero when modifying {attribute_name} on {self.name}.")
                      return 0 # No change on division by zero
                 new_value = old_value / value
            else:
                 print(f"Warning: Unknown operation '{operation}' for attribute '{attribute_name}'.")
                 return 0 # Return 0 change
        except Exception as e:
             print(f"Error applying operation '{operation}' with value {value} on {attribute_name}: {e}")
             return 0 # Return 0 change

        # --- Apply Attribute-Specific Logic (like HP clamping) ---
        if attribute_name == "hp":
            # HP must be between 0 and max_hp
            new_value = max(0, min(new_value, self.max_hp))
        # Add other attribute-specific logic here if needed (e.g., damage minimum)

        # --- Update Attribute and Calculate Change ---
        setattr(self, attribute_name, new_value)
        actual_change = new_value - old_value

        # For saving results, we often want the magnitude of the change (e.g., damage taken, heal received)
        # Or the calculated value before clamping. Let's save the magnitude of the change for simplicity
        # in common cases like damage dealt/heal received.
        return abs(actual_change)


# Helper dictionary for value calculation operations
VALUE_OPERATIONS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": lambda a, b: a / b if b != 0 else math.inf # Handle division by zero
}


class Action:
    """
    Represents a data-driven action defined by a list of effects.
    Configuration is a list of dictionaries, where each dictionary describes an effect.
    """
    def __init__(self, config):
        if not isinstance(config, list):
            raise ValueError("Action configuration must be a list of effects.")
        self.config = config

    def _calculate_value(self, value_config, actor, target, context):
        """Recursively calculates a value based on the value configuration."""
        if isinstance(value_config, (int, float)):
            # Allow simple literals directly for convenience, treat as {"type": "literal", "value": value_config}
            value_config = {"type": "literal", "value": value_config}

        if not isinstance(value_config, dict) or "type" not in value_config:
            raise ValueError(f"Invalid value configuration format: {value_config}")

        value_type = value_config["type"]

        if value_type == "literal":
            if "value" not in value_config:
                 raise ValueError(f"Literal value config missing 'value': {value_config}")
            return value_config["value"]

        elif value_type == "attribute":
            if "source" not in value_config or "attribute" not in value_config:
                 raise ValueError(f"Attribute value config missing 'source' or 'attribute': {value_config}")
            source_char = actor if value_config["source"] == "actor" else target
            if source_char is None:
                 raise ValueError(f"Attribute source '{value_config['source']}' is invalid (e.g., target was None).")
            if not hasattr(source_char, value_config["attribute"]):
                 print(f"Warning: Character '{source_char.name}' does not have attribute '{value_config['attribute']}'. Defaulting value to 0.")
                 return 0 # Or raise error depending on desired strictness
            return getattr(source_char, value_config["attribute"])

        elif value_type == "operation":
            if "op" not in value_config or "operands" not in value_config or not isinstance(value_config["operands"], list):
                 raise ValueError(f"Operation value config missing 'op' or 'operands' list: {value_config}")
            op_func = VALUE_OPERATIONS.get(value_config["op"])
            if not op_func:
                 raise ValueError(f"Unknown operation '{value_config['op']}' in value config: {value_config}")

            operands = [self._calculate_value(operand_config, actor, target, context) for operand_config in value_config["operands"]]

            # Apply operation iteratively (e.g., add all numbers, multiply all)
            if not operands:
                 return 0 # Or raise error? Operation with no operands doesn't make sense.
            result = operands[0]
            for operand in operands[1:]:
                 result = op_func(result, operand)
            return result

        elif value_type == "result_of_name":
            if "name" not in value_config:
                 raise ValueError(f"Result_of_name value config missing 'name': {value_config}")
            result_name = value_config["name"]
            if result_name not in context:
                # This is a common misconfiguration - dependency not met or misspelled name
                raise ValueError(f"Result '{result_name}' not found in execution context. Check 'save_result_as' names and effect order.")
            return context[result_name]

        else:
            raise ValueError(f"Unknown value calculation type: {value_type}")


    def execute(self, actor, target):
        """Executes the action's effects on the actor and target."""
        print(f"\n--- {actor.name} uses an action on {target.name} ---")
        print(f"Before: Actor: {actor}, Target: {target}")

        # Context to store results of effects for later reference
        execution_context = {}

        for i, effect_config in enumerate(self.config):
            print(f"  Applying Effect {i}: {effect_config.get('target', '???')} {effect_config.get('operation', '???')} {effect_config.get('attribute', '???')}")
            try:
                # Determine the character the effect applies to
                target_specifier = effect_config.get("target")
                if target_specifier == "actor":
                    target_char = actor
                elif target_specifier == "target":
                    target_char = target
                else:
                    raise ValueError(f"Effect {i} has invalid target '{target_specifier}'. Must be 'actor' or 'target'.")

                attribute_name = effect_config.get("attribute")
                operation = effect_config.get("operation")
                value_config = effect_config.get("value")
                save_as_name = effect_config.get("save_result_as")

                if attribute_name is None or operation is None or value_config is None:
                     raise ValueError(f"Effect {i} is missing 'attribute', 'operation', or 'value'.")

                # Calculate the value for this effect
                calculated_value = self._calculate_value(value_config, actor, target, execution_context)
                print(f"    Calculated value: {calculated_value}")

                # Apply the effect's operation to the target character's attribute
                # Use the Character's generic modify_attribute method
                actual_change = target_char.modify_attribute(attribute_name, operation, calculated_value)
                print(f"    Actual change to {target_char.name}'s {attribute_name}: {actual_change}")

                # Save the result if requested
                if save_as_name:
                    execution_context[save_as_name] = abs(actual_change) # Save the magnitude of the change
                    print(f"    Saved result as '{save_as_name}': {execution_context[save_as_name]}")

            except ValueError as e:
                print(f"Error applying effect {i}: {e}")
            except Exception as e:
                 print(f"An unexpected error occurred applying effect {i}: {e}")


        print(f"After:  Actor: {actor}, Target: {target}")
        print("--------------------------------------------")


