        protected override void OnStop()
        {
            _eventLog.WriteEntry("Service is stopping.");

            // Signal the capture thread to stop
            _stopCapture = true;

            // Wait for the capture thread to finish (with a timeout)
            if (_captureThread != null && _captureThread.IsAlive)
            {
                _captureThread.Join(TimeSpan.FromSeconds(10)); // Wait up to 10 seconds
                if (_captureThread.IsAlive)
                {
                    _eventLog.WriteEntry("Capture thread did not stop gracefully. Aborting.", EventLogEntryType.Warning);
                    _captureThread.Abort(); // Force stop if necessary (use with caution)
                }
            }

            // Close the communicator and device
            if (_communicator != null)
            {
                _communicator.Dispose();
                _communicator = null;
            }
            // Note: LivePacketDevice does not have a Dispose() or Close() method in Pcap.Net
            // The communicator's Dispose handles the underlying libpcap/Npcap handle.

            _eventLog.WriteEntry("Service stopped.");
        }

        private void CapturePackets()
        {
            try
            {
                // Retrieve the list of available devices
                IList<LivePacketDevice> allDevices = LivePacketDevice.AllLocalDevices;

                if (allDevices.Count == 0)
                {
                    _eventLog.WriteEntry("No network adapters found. Cannot capture.", EventLogEntryType.Error);
                    RequestAdditionalTime(5000); // Request more time before stopping
                    Stop(); // Stop the service
                    return;
                }

                // Select the adapter based on configuration
                // A more robust selection would handle multiple adapters or specific criteria
                _selectedDevice = null;
                if (!string.IsNullOrEmpty(_adapterName))
                {
                    _selectedDevice = allDevices.FirstOrDefault(d => d.Name.Contains(_adapterName) ||
                                                                      (d.Description != null && d.Description.Contains(_adapterName)));
                }

                // Fallback to the first device if no name is configured or found
                if (_selectedDevice == null)
                {
                     _eventLog.WriteEntry($"Adapter '{_adapterName}' not found or AdapterName not configured. Using the first adapter found.", EventLogEntryType.Warning);
                    _selectedDevice = allDevices[0];
                }

                _eventLog.WriteEntry($"Selected adapter: {_selectedDevice.Description} ({_selectedDevice.Name})");

                // Open the device
                // Open flags:
                // PacketDeviceOpenAttributes.Promiscuous: Capture all packets, not just those addressed to the adapter.
                // 1000: Read timeout in milliseconds.
                // PacketDeviceOpenAttributes.DataTransferUdp: Use UDP-like data transfer (more reliable than raw sockets on Windows).
                // 65536: Capture buffer size (max snapshot length).
                 _communicator = _selectedDevice.Open(
                    65536, // Max buffer size / snapshot length
                    PacketDeviceOpenAttributes.Promiscuous | PacketDeviceOpenAttributes.DataTransferUdp, // Flags
                    1000); // Read timeout (milliseconds)

                // Apply BPF filter if configured
                if (!string.IsNullOrEmpty(_bpfFilter))
                {
                    try
                    {
                        _communicator.SetFilter(_bpfFilter);
                         _eventLog.WriteEntry($"Applied BPF filter: {_bpfFilter}");
                    }
                    catch (Exception filterEx)
                    {
                         _eventLog.WriteEntry($"Failed to apply BPF filter '{_bpfFilter}': {filterEx.Message}", EventLogEntryType.Error);
                         // Decide if you want to stop the service or continue without filter
                         // For this example, we'll log and continue without the filter.
                    }
                }


                // Start the capture loop
                _eventLog.WriteEntry("Starting packet capture loop.");

                // Use ReceivePacket method in a loop
                Packet packet;
                while (!_stopCapture)
                {
                    PacketCommunicatorReceiveResult result = _communicator.ReceivePacket(out packet);

                    switch (result)
                    {
                        case PacketCommunicatorReceiveResult.Ok:
                            // Packet received successfully, process it
                            ProcessPacket(packet);
                            break;

                        case PacketCommunicatorReceiveResult.Timeout:
                            // Timeout elapsed, no packet received. Continue loop.
                            // This allows the loop to check the _stopCapture flag.
                            break;

                        case PacketCommunicatorReceiveResult.Eof:
                            // The interface was closed. This shouldn't happen in a service unless there's an external issue.
                            _eventLog.WriteEntry("Packet capture reached EOF. Stopping capture.", EventLogEntryType.Warning);
                            _stopCapture = true; // Signal stop
                            break;

                        case PacketCommunicatorReceiveResult.NotYetOpen:
                            _eventLog.WriteEntry("Communicator not yet open. Stopping capture.", EventLogEntryType.Error);
                            _stopCapture = true; // Signal stop
                            break;

                        case PacketCommunicatorReceiveResult.Error:
                             _eventLog.WriteEntry("Error receiving packet. Stopping capture.", EventLogEntryType.Error);
                            _stopCapture = true; // Signal stop
                            break;
                    }
                }

                 _eventLog.WriteEntry("Packet capture loop stopped.");

            }
            catch (ThreadAbortException)
            {
                // Expected when the thread is aborted during service stop
                 _eventLog.WriteEntry("Capture thread aborted.", EventLogEntryType.Warning);
            }
            catch (Exception ex)
            {
                // Log any unexpected errors in the capture thread
                _eventLog.WriteEntry($"Critical error in capture thread: {ex.Message}\n{ex.StackTrace}", EventLogEntryType.Error);
                // Consider stopping the service gracefully on critical errors
                 RequestAdditionalTime(5000); // Request more time before stopping
                 Stop(); // Stop the service
            }
        }

        private void ProcessPacket(Packet packet)
        {
            // --- Packet Decoding Logic ---
            // Pcap.NET automatically dissects common layers.
            // You access layers by extracting them.

            StringBuilder packetInfo = new StringBuilder();
            packetInfo.AppendLine($"--- Packet Received at {packet.Timestamp.ToString("yyyy-MM-dd HH:mm:ss.fff")} ---");

            // 1. Ethernet Layer
            EthernetLayer ethernetLayer = packet.Extract<EthernetLayer>();
            if (ethernetLayer != null)
            {
                packetInfo.AppendLine($"  Ethernet: {ethernetLayer.Source} -> {ethernetLayer.Destination}, Type: {ethernetLayer.EtherType}");

                // 2. IP Layer (IPv4 or IPv6)
                IpV4Layer ipV4Layer = packet.Extract<IpV4Layer>();
                if (ipV4Layer != null)
                {
                    packetInfo.AppendLine($"    IPv4: {ipV4Layer.Source} -> {ipV4Layer.Destination}, Protocol: {ipV4Layer.Protocol}");

                    // 3. Transport Layer (TCP or UDP)
                    TcpLayer tcpLayer = packet.Extract<TcpLayer>();
                    if (tcpLayer != null)
                    {
                        packetInfo.AppendLine($"      TCP: {tcpLayer.SourcePort} -> {tcpLayer.DestinationPort}, Flags: {tcpLayer.ControlBits}");
                        // Access payload: tcpLayer.Payload
                        // Decode application data (e.g., HTTP, TLS) here based on ports/protocol
                        // Example: Basic check for HTTP (port 80 or 8080)
                        if (tcpLayer.SourcePort == 80 || tcpLayer.DestinationPort == 80 ||
                            tcpLayer.SourcePort == 8080 || tcpLayer.DestinationPort == 8080)
                        {
                             packetInfo.AppendLine("        Potentially HTTP traffic.");
                             // You would add code here to parse the tcpLayer.Payload.ToASCIIString()
                             // or ToArray() to look for HTTP headers/body.
                        }
                         if (tcpLayer.SourcePort == 443 || tcpLayer.DestinationPort == 443)
                        {
                             packetInfo.AppendLine("        Potentially TLS/HTTPS traffic.");
                             // Decoding TLS payload is complex and requires a dedicated library.
                             // You might just note its presence here.
                        }
                    }
                    else
                    {
                        UdpLayer udpLayer = packet.Extract<UdpLayer>();
                        if (udpLayer != null)
                        {
                            packetInfo.AppendLine($"      UDP: {udpLayer.SourcePort} -> {udpLayer.DestinationPort}");
                             // Access payload: udpLayer.Payload
                             // Decode application data here (e.g., DNS, NTP)
                             if (udpLayer.SourcePort == 53 || udpLayer.DestinationPort == 53)
                            {
                                 packetInfo.AppendLine("        Potentially DNS traffic.");
                                 // You would add code here to parse the udpLayer.Payload for DNS query/response.
                            }
                        }
                         else
                        {
                             // Other IP protocols like ICMP, IGMP, etc.
                             packetInfo.AppendLine($"      Other IP Protocol: {ipV4Layer.Protocol}");
                        }
                    }
                }
                else
                {
                    IpV6Layer ipV6Layer = packet.Extract<IpV6Layer>();
                     if (ipV6Layer != null)
                    {
                         packetInfo.AppendLine($"    IPv6: {ipV6Layer.Source} -> {ipV6Layer.Destination}, Next Header: {ipV6Layer.NextHeader}");
                         // Add logic for IPv6 transport layers (TCP/UDP) similarly
                    }
                     else
                    {
                         // Non-IP Ethernet traffic (e.g., ARP)
                         packetInfo.AppendLine($"    Non-IP traffic (EtherType: {ethernetLayer.EtherType})");
                    }
                }
            }
            else
            {
                packetInfo.AppendLine("  Non-Ethernet packet."); // e.g., PPP, Loopback
            }

            // Log the decoded information (using Event Log for simplicity, file logging is better for volume)
            // WARNING: Logging every packet to the Event Log will fill it up quickly!
            // For a real service, you'd filter what you log or use a file logger.
            // For demonstration, we'll just log a summary line or log to a file.

            // Option 1: Log a summary to Event Log (less verbose)
             LogPacketSummary(packetInfo.ToString());

            // Option 2: Log full packet info to a file (more verbose, requires file path config and handling)
            // LogPacketToFile(packetInfo.ToString());

            // Option 3: Process the data further (send to database, monitoring system, etc.)
            // ... your custom processing logic here ...
        }

        private void LogPacketSummary(string fullPacketInfo)
        {
            // Extract a summary line (e.g., source/dest) and log that to Event Log
            // Or just log the full info for demonstration (be cautious!)
             try
            {
                 // Simple summary extraction
                 string summary = fullPacketInfo.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
                                                 .FirstOrDefault(line => line.Trim().StartsWith("IPv4:") || line.Trim().StartsWith("IPv6:") || line.Trim().StartsWith("Ethernet:")) ?? "Unknown Packet";
                 _eventLog.WriteEntry($"Packet: {summary}", EventLogEntryType.Information, 1); // Use a specific event ID
            }
             catch (Exception ex)
             {
                  // Avoid crashing the service if logging fails
                 // Consider logging this error to a separate file if Event Log is full/issue
             }
        }

        // Example of how you might log to a file (requires more setup)
        /*
        private void LogPacketToFile(string packetInfo)
        {
