             }
        }
        */

        // Optional: Implement OnPause, OnContinue, OnShutdown if needed
        protected override void OnPause()
        {
             _eventLog.WriteEntry("Service paused.");
             // You would need to add logic here to pause the capture loop
             // This might involve a flag that the capture loop checks.
        }

        protected override void OnContinue()
        {
             _eventLog.WriteEntry("Service continued.");
             // You would add logic here to resume the capture loop
        }

        protected override void OnShutdown(ShutdownEventArgs args)
