**Example 2: Changing Layout (Row vs Column)**

```kotlin
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.layout.*
import androidx.compose.material3.Button
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp

@Composable
fun ResponsiveLayoutExample() {
    ContainerQueryLayout(
        modifier = Modifier
            .fillMaxWidth(0.9f) // Make the container less than full width
            .heightIn(min = 150.dp, max = 300.dp) // Give it some height flexibility
            .border(2.dp, Color.Gray)
            .padding(8.dp)
    ) { containerInfo ->
        val itemModifier = Modifier.weight(1f).padding(4.dp)

        if (containerInfo.isCompactWidth) {
            Column(
                modifier = Modifier.fillMaxSize(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.SpaceEvenly
            ) {
                Text("Compact Layout", modifier = Modifier.padding(bottom = 8.dp))
                Button(onClick = {}, modifier = itemModifier) { Text("Button 1") }
                Button(onClick = {}, modifier = itemModifier) { Text("Button 2") }
            }
        } else { // Medium or Expanded
            Row(
                modifier = Modifier.fillMaxSize(),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceEvenly
            ) {
                Text("Wide Layout", modifier = Modifier.padding(end = 16.dp))
                Button(onClick = {}, modifier = itemModifier) { Text("Button 1") }
                Button(onClick = {}, modifier = itemModifier) { Text("Button 2") }
            }
        }
    }
}

