@Composable
fun ResponsiveChildExample() {
    ContainerQueryLayout(
        modifier = Modifier
            .width(250.dp) // Give it a fixed width to control the example
            .height(80.dp)
            .border(2.dp, Color.Gray)
            .padding(8.dp)
    ) { containerInfo ->
        // A button whose content changes based on container width
        Button(
            onClick = { /* Do something */ },
            modifier = Modifier
                .fillMaxSize()
        ) {
            if (containerInfo.isCompactWidth) {
                Icon(Icons.Filled.Add, contentDescription = "Add")
            } else {
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Icon(Icons.Filled.Add, contentDescription = "Add", modifier = Modifier.padding(end = 4.dp))
                    Text("Add Item")
                }
            }
        }
    }
}

